-- A claim's status: DRAFT when added; DRAFT -> OPEN -> SETTLED, and DRAFT or OPEN -> VOID. SETTLED
-- and VOID are final. Only OPEN and SETTLED claims count toward claimed and due.
ALTER TABLE claim ADD COLUMN status VARCHAR(10) DEFAULT 'DRAFT' NOT NULL
    CHECK (status IN ('DRAFT', 'OPEN', 'SETTLED', 'VOID'));
-- A claim's number: given when it is opened, the next on its sheet (1, 2, ...), never reused. A
-- draft has none, and voiding clears it. The sheet keeps the last number it gave out.
ALTER TABLE claim ADD COLUMN number INT;
ALTER TABLE sheet ADD COLUMN last_claim_number INT DEFAULT 0 NOT NULL;
UPDATE claim c SET number = (
    SELECT COUNT(*) FROM claim o
    WHERE o.sheet_id = c.sheet_id AND o.status IN ('OPEN', 'SETTLED') AND o.id <= c.id)
WHERE c.status IN ('OPEN', 'SETTLED');
UPDATE sheet s SET last_claim_number = COALESCE((SELECT MAX(number) FROM claim c WHERE c.sheet_id = s.id), 0);
CREATE UNIQUE INDEX claim_sheet_number ON claim (sheet_id, number);
-- A settled claim's due, fixed when it is settled: its amount times its person's grade's rate then,
-- rounded half up to cents. Later changes to rates (or grades) do not alter it. Open and other
-- claims have none (their due stays live), as does one settled while its grade had no rate.
ALTER TABLE claim ADD COLUMN due DECIMAL(15, 2);
UPDATE claim c SET due = (
    SELECT ROUND(c.amount * r.pct / 100, 2) FROM person p JOIN rate r
        ON r.sheet_id = p.sheet_id AND r.grade = p.grade
    WHERE p.id = c.person_id)
WHERE c.status = 'SETTLED';
